from ail import read_bytes, write_bytes
# UTF-8 hexadecimal files; decoding accepts ASCII whitespace between byte pairs.
def hex_file_write(path: str, data: bytes) -> int:
    text = data.hex()
    write_bytes(path, text.encode())
    return len(data)

def hex_file_read(path: str) -> bytes:
    text = read_bytes(path).decode()
    return bytes.fromhex(text)
